for _bank in BANKS:
    for _item in _bank[3]:
        if _item["concept_id"] in EN_OPTION_REWRITES:
            _item["options"] = EN_OPTION_REWRITES[_item["concept_id"]]
            _item["options_en"] = _item["options"]
        if _item["concept_id"] in AR_OPTION_REWRITES:
            _item["options_ar"] = AR_OPTION_REWRITES[_item["concept_id"]]

def rotate(options, shift):
    return [options[(i - shift) % 4] for i in range(4)]

def main():
    RETIRED.mkdir(exist_ok=True)
    for quiz_id, topic_en, topic_ar, items in BANKS:
        assert 8 <= len(items) <= 16, (quiz_id, len(items))
        assert len({item["concept_id"] for item in items}) == len(items), quiz_id
        bank = dict(HEADER)
        bank.update({"quiz_id": quiz_id, "topic": topic_en, "topic_ar": topic_ar,
                     "questions": []})
        for index, item in enumerate(items):
            target = "ABCD"[index % 4]
            shift = LETTERS.index(target)
            out = dict(item)
            out["id"] = "q%d" % (index + 1)
            out["options"] = rotate(item["options"], shift)
            out["options_en"] = out["options"]
            out["options_ar"] = rotate(item["options_ar"], shift)
            out["answer"] = target
            out["correct"] = shift
            bank["questions"].append(out)
        path = ROOT / (quiz_id + ".json")
        rendered = json.dumps(bank, ensure_ascii=False, indent=2) + "\n"
        if path.exists() and path.read_text(encoding="utf-8") == rendered:
            print("unchanged %s  %d questions" % (quiz_id, len(items)))
            continue
        if path.exists():
            dest = RETIRED / path.name
            suffix = 2
            while dest.exists():
                dest = RETIRED / (path.stem + "__draft_%02d.json" % suffix)
                suffix += 1
            shutil.move(str(path), str(dest))
        path.write_text(rendered, encoding="utf-8")
        print("wrote %s  %d questions" % (quiz_id, len(items)))

if __name__ == "__main__":
    LETTERS = "ABCD"
    main()
